def process_sequence():
    import sys
    input = sys.stdin.read
    data = list(map(int, input().split()))

    n = data[0]
    a = data[1:]

    if n == 0:
        print(0)
        return

    b = [1] * n
    for i in range(1, n):
        if a[i] > b[i - 1]:
            b[i] = b[i - 1] + 1
        else:
            b[i] = a[i]

    c = [1] * n
    for i in range(n - 2, -1, -1):
        if a[i] > c[i + 1]:
            c[i] = c[i + 1] + 1
        else:
            c[i] = a[i]

    max_pyramid_size = 0
    for i in range(n):
        max_pyramid_size = max(max_pyramid_size, min(b[i], c[i]))

    print(max_pyramid_size)
